-- ============================================================
-- Cryptic Tide -- 50 Pre-Created Teams Seed Script
-- Passwords are strictly bcrypt-hashed.
-- ============================================================

ON CONFLICT (team_lead_email) DO UPDATE SET
  team_number = EXCLUDED.team_number,
  team_name = EXCLUDED.team_name,
  password_hash = EXCLUDED.password_hash,
  is_active = TRUE;

-- Seed captain entries into team_members
SELECT id, team_lead_name, team_lead_email FROM public.teams
ON CONFLICT DO NOTHING;
